style.content:
/* Hide the real select, but keep it in the form */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* The fake closed control */
[role="combobox"] {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 0 0.7rem;
  min-height: 3.6rem;
  padding: 0.4rem 0.8rem;
  background: #fff;
  border: 1px solid #cbc4b4;
  border-radius: 0.8rem;
  cursor: pointer;
}

/* The arrow, added by hand */
[role="combobox"]::after {
  content: "";
  grid-area: 1 / 3 / span 2;
  width: 0.65rem;
  height: 0.55rem;
  background: currentColor;
  clip-path: polygon(0 0, 100% 0, 50% 100%);
  transition: rotate 0.2s;
}

[role="combobox"][aria-expanded="true"] {
  border-color: #4636c9;
  box-shadow: 0 0 0 3px #eceaff;
}

[role="combobox"][aria-expanded="true"]::after {
  rotate: 180deg;
}

/* The fake list, positioned under the control */
[role="listbox"] {
  position: absolute;
  top: calc(100% + 0.4rem);
  left: 0;
  right: 0;
  z-index: 10;
  max-height: 17rem;
  margin: 0;
  padding: 0.35rem;
  overflow: auto;
  list-style: none;
  background: #fff;
  border: 1px solid #cbc4b4;
  border-radius: 0.9rem;
  box-shadow: 0 24px 50px -20px rgb(28 27 34 / 0.45);
}

[role="option"] {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 0 0.7rem;
  padding: 0.45rem 0.6rem;
  border-radius: 0.6rem;
  cursor: pointer;
}

[role="option"]:hover,
[role="option"].active {
  background: #f3f0e8;
}

[role="option"][aria-selected="true"] {
  background: #eceaff;
}

[role="option"][aria-disabled="true"] {
  opacity: 0.4;
  cursor: not-allowed;
}

style.hiddenContent:
/* Preview frame shared by every view (from Lunch and Learn Simple's simple.css).
   Nothing in here is part of any demo. */
:root {
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: clamp(15px, 0.55vw + 9px, 21px);
  color: #1c1b22;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
}

:focus-visible {
  outline: 3px solid #1f6feb;
  outline-offset: 2px;
}

/* The demo area fills the preview. */
.stage {
  position: relative;
  height: 100vh;
  overflow: hidden;
  background: #fff;
}

/* Note shown by unsupported.js when the browser lacks the feature. */
.unsupported {
  position: absolute;
  left: 0.8rem;
  bottom: 0.8rem;
  z-index: 100;
  display: flex;
  align-items: baseline;
  gap: 0.45rem;
  max-width: min(26rem, calc(100% - 1.6rem));
  margin: 0;
  padding: 0.35rem 0.75rem;
  font-size: 0.72rem;
  line-height: 1.4;
  color: #b42318;
  background: rgb(253 233 230 / 0.95);
  border: 1px solid #f1b8b0;
  border-radius: 0.6rem;
  pointer-events: none;
}

.unsupported::before {
  content: '';
  flex: none;
  width: 0.45rem;
  height: 0.45rem;
  background: #e5372b;
  border-radius: 50%;
}

.unsupported b {
  color: #8f1d14;
}

/* Page and option-content looks only, shared by before and after.
   The control itself is styled on each page, in the code that is shown. */

.stage {
  display: grid;
  place-items: start center;
  padding-top: 4rem;
  background: #f8f6f1;
}

.field {
  width: 24rem;
  padding: 1.4rem 1.5rem 1.6rem;
  background: #fff;
  border: 1px solid #e4dfd4;
  border-radius: 1.1rem;
  box-shadow: 0 20px 50px -30px rgb(28 27 34 / 0.5);
}

.field-control {
  position: relative;
}

.field-control + .field-control {
  margin-top: 1.2rem;
}

.field label {
  display: block;
  margin-bottom: 0.4rem;
  font-weight: 700;
}

/* A person: avatar, name, role (inside options and the closed control) */
.field img {
  grid-row: span 2;
  width: 2.4rem;
  height: 2.4rem;
  border-radius: 50%;
}

.field small {
  grid-column: 2;
  font-size: 0.8rem;
  color: #77748a;
}

/* The separator inside <small> is only there for the plain native select, which shows the
   option's text ("Ava Lindqvist · Design lead"). Where the select is customizable, the role
   gets its own line and the separator is in the way. */
.field small span {
  display: none;
}

script.content:
function setupSelect(field) {
  const label = field.querySelector('label');
  const select = field.querySelector('select');
  const combo = field.querySelector('[role="combobox"]');
  const list = field.querySelector('[role="listbox"]');
  const options = [...list.querySelectorAll('[role="option"]')];

  let active = select.selectedIndex;
  const isDisabled = (i) => select.options[i].disabled;

  // Show the selected person in the closed control
  function render() {
    options.forEach((o, i) => o.setAttribute('aria-selected', String(i === select.selectedIndex)));
    combo.replaceChildren(...options[select.selectedIndex].cloneNode(true).childNodes);
  }

  function open() {
    list.hidden = false;
    combo.setAttribute('aria-expanded', 'true');
    setActive(select.selectedIndex);
  }

  function close() {
    list.hidden = true;
    combo.setAttribute('aria-expanded', 'false');
    combo.removeAttribute('aria-activedescendant');
  }

  // The highlighted option (keyboard focus stays on the combobox)
  function setActive(i) {
    options[active].classList.remove('active');
    active = i;
    options[i].classList.add('active');
    combo.setAttribute('aria-activedescendant', options[i].id);
    const o = options[i];
    if (o.offsetTop < list.scrollTop) list.scrollTop = o.offsetTop;
    if (o.offsetTop + o.offsetHeight > list.scrollTop + list.clientHeight) {
      list.scrollTop = o.offsetTop + o.offsetHeight - list.clientHeight;
    }
  }

  // Write the choice back to the real select and tell the page
  function choose(i) {
    if (isDisabled(i)) return;
    select.selectedIndex = i;
    select.dispatchEvent(new Event('change', { bubbles: true }));
    render();
    close();
  }

  // Next option in a direction, skipping disabled ones
  function step(from, direction) {
    for (let i = from + direction; i >= 0 && i < options.length; i += direction) {
      if (!isDisabled(i)) return i;
    }
    return from;
  }

  // Mouse
  combo.addEventListener('click', () => (list.hidden ? open() : close()));
  list.addEventListener('pointerdown', (e) => e.preventDefault());
  list.addEventListener('click', (e) => {
    const option = e.target.closest('[role="option"]');
    if (option) choose(options.indexOf(option));
  });
  combo.addEventListener('blur', close);
  label.addEventListener('click', (e) => {
    e.preventDefault();
    combo.focus();
  });

  // Keyboard
  combo.addEventListener('keydown', (e) => {
    if (list.hidden) {
      if (['ArrowDown', 'ArrowUp', 'Enter', ' '].includes(e.key)) {
        e.preventDefault();
        open();
      }
      return;
    }
    if (e.key === 'ArrowDown') setActive(step(active, 1));
    else if (e.key === 'ArrowUp') setActive(step(active, -1));
    else if (e.key === 'Home') setActive(step(-1, 1));
    else if (e.key === 'End') setActive(step(options.length, -1));
    else if (e.key === 'Enter' || e.key === ' ') choose(active);
    else if (e.key === 'Escape') close();
    else if (e.key.length === 1) {
      // Type a letter to jump to the next name that starts with it
      const letter = e.key.toLowerCase();
      for (let k = 1; k <= options.length; k++) {
        const i = (active + k) % options.length;
        if (!isDisabled(i) && select.options[i].text.toLowerCase().startsWith(letter)) {
          setActive(i);
          break;
        }
      }
    } else return;
    e.preventDefault();
  });

  // Form reset changes the real select; update the fake one afterwards
  select.form.addEventListener('reset', () => setTimeout(render));
}

document.querySelectorAll('.field-control').forEach(setupSelect);
